package com.crms.controller;import com.crms.repository.ApplicationRepository;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/reports") @PreAuthorize("hasAnyRole('ADMIN','PLACEMENT_OFFICER')") public class ReportController{private final ApplicationRepository apps;public ReportController(ApplicationRepository a){apps=a;}@GetMapping(value="/applications.csv",produces="text/csv")public ResponseEntity<String> applications(){var b=new StringBuilder("id,job,status,company,createdAt\n");apps.findAll().forEach(a->b.append(a.getId()).append(',').append(a.getJob().getTitle().replace(',',' ')).append(',').append(a.getStatus()).append(',').append(a.getJob().getCompany().getName().replace(',',' ')).append(',').append(a.getCreatedAt()).append('\n'));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=applications.csv").body(b.toString());}}
